import{_ as a,o as e,c as n,ah as o}from"./chunks/framework.D4KxWb5R.js";const p=JSON.parse('{"title":"Accounts and access","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/administration/accounts.md","filePath":"src/en/guide/administration/accounts.md"}'),i={name:"en/guide/administration/accounts.md"};function s(c,t,r,d,h,l){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="accounts-and-access" tabindex="-1">Accounts and access <a class="header-anchor" href="#accounts-and-access" aria-label="Permalink to &quot;Accounts and access&quot;">​</a></h1><p><strong>Administration → Accounts</strong> is for the CEO only. <strong>Administration → Offboarding</strong> is open to the CEO and to HR &amp; Legal Affairs.</p><h2 id="the-account-list" tabindex="-1">The account list <a class="header-anchor" href="#the-account-list" aria-label="Permalink to &quot;The account list&quot;">​</a></h2><p>It shows, for each person, their position, department, status and invitation state (<strong>Invitation pending</strong>, <strong>Invitation expired</strong>, <strong>Activated</strong>). Search by name or e-mail, filter by position or status, and use <strong>Export CSV</strong> to get the filtered list.</p><h2 id="inviting-someone" tabindex="-1">Inviting someone <a class="header-anchor" href="#inviting-someone" aria-label="Permalink to &quot;Inviting someone&quot;">​</a></h2><ol><li><strong>New account</strong>.</li><li><strong>Identity</strong>: name, e-mail (the address the invitation goes to), language of the invitation and the interface, and, if needed, <strong>Require two-factor authentication</strong> for this account.</li><li><strong>Position</strong> and <strong>department</strong> (optional).</li><li><strong>Scope</strong>, depending on the position: <ul><li>Support L1 and L2: the products, zones and offices the person works on, with at least one product;</li><li>CEO and heads: all products and all zones, nothing to choose;</li><li>HR and Finance: cross-cutting, no product or zone.</li></ul></li><li><strong>Product back-office access</strong>: tick the products whose back-office the person may open (see below).</li><li><strong>Create account</strong>.</li></ol><p>The invitation e-mail is sent at once, with a temporary password valid for the duration set in the <a href="./settings.html">configuration</a> (7 days by default). The person chooses their own password at first sign-in.</p><h3 id="resending-an-invitation" tabindex="-1">Resending an invitation <a class="header-anchor" href="#resending-an-invitation" aria-label="Permalink to &quot;Resending an invitation&quot;">​</a></h3><p>An expired invitation is never renewed automatically. On the account page, <strong>Send a new invitation</strong> sends a new temporary password; the old one stops working.</p><h2 id="changing-a-position-scope-or-access" tabindex="-1">Changing a position, scope or access <a class="header-anchor" href="#changing-a-position-scope-or-access" aria-label="Permalink to &quot;Changing a position, scope or access&quot;">​</a></h2><p>Open the account, edit, then save. The change applies on the person&#39;s next request, without signing in again. They are notified (&quot;Your access&quot; notification).</p><p>If you edit your own account, changing your position may remove your access to this page.</p><h2 id="product-back-office-access" tabindex="-1">Product back-office access <a class="header-anchor" href="#product-back-office-access" aria-label="Permalink to &quot;Product back-office access&quot;">​</a></h2><p>SSO opens <strong>no</strong> back-office by default. A person opens a product&#39;s back-office:</p><ul><li>if access is granted on their account, account by account, whatever their scope;</li><li>or if they belong to a <a href="./teams.html">team</a> responsible for the product.</li></ul><p>The account page shows team-based access separately (&quot;Through a team: …&quot;). Removing granted access leaves open a product the person keeps through a team. When someone loses their last access to a product, their sessions and tokens for that back-office are revoked immediately.</p><p>What the person can do <strong>inside</strong> the back-office depends on their position: for Auticway, see <a href="./../auticway.html">Auticway back-office</a>.</p><h2 id="disabling-an-account" tabindex="-1">Disabling an account <a class="header-anchor" href="#disabling-an-account" aria-label="Permalink to &quot;Disabling an account&quot;">​</a></h2><p>An account is never deleted: it is disabled.</p><ol><li><strong>Offboarding</strong> (or <strong>Disable</strong> in the account list).</li><li>Find the person, then <strong>Disable</strong> and confirm.</li></ol><p>The person is signed out everywhere immediately, M&#39;City IQ and product back-offices included, and their back-office access is removed. The account and its history are kept.</p><p>Nobody can disable their own account, and the last active CEO account cannot be disabled.</p><h3 id="reactivating-an-account" tabindex="-1">Reactivating an account <a class="header-anchor" href="#reactivating-an-account" aria-label="Permalink to &quot;Reactivating an account&quot;">​</a></h3><p>The CEO can <strong>Reactivate</strong> a disabled account. The person can sign in again, but their product back-office access is not restored: grant it again from their account page.</p>',24)])])}const g=a(i,[["render",s]]);export{p as __pageData,g as default};
